import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/shapes_editor.DJzoZ_E0.svg",m=JSON.parse('{"title":"Shapes","description":"","frontmatter":{},"headers":[],"relativePath":"generators/SHAPES.md","filePath":"generators/SHAPES.md"}'),r={name:"generators/SHAPES.md"};function h(i,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="shapes" tabindex="-1">Shapes <a class="header-anchor" href="#shapes" aria-label="Permalink to &quot;Shapes&quot;">​</a></h1><p>A Shapes generator shapes a section over time in three ways at once, each a percentage that ramps from a start to an end, which <a href="./../GENERATORS#shapes">Generators</a> describes: where each is set, which wins, and the settings they share.</p><ul><li><strong>Density</strong> keeps a share of a clip&#39;s notes, the strongest places in the bar first: the bar&#39;s start, then its middle, the other beats, the eighths and last the sixteenths. At 100% every note plays, at 50% the sixteenths between the eighths drop out, at 25% only the beats are left, and at 0% nothing. A chord is kept or dropped whole, and drums are thinned too, so one full pattern gives a build, a breakdown or a fill. It runs from 0% to 100%.</li><li><strong>Swell</strong> scales each note&#39;s velocity, held from 1 to 127, for crescendos and fades, from 0% to 200%. Its Swell accent makes the beats louder still, up to 50%.</li><li><strong>Articulate</strong> scales how long each note sounds, compared with what the pattern writes, from 10% to 200%. Shorter leaves a gap before the next note; longer holds a note over a rest after it, but never past where the next note starts or past the clip&#39;s end.</li></ul><p>A shape whose Start and End are both blank does nothing, so a Shapes generator that sets only its Density leaves a clip&#39;s own Articulate in force.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+o+'" alt="A Shapes generator&#39;s settings"></p><p>Each shape is a section, <code>+ Density</code>, <code>+ Swell</code> and <code>+ Articulate</code>, closed until opened and saying <code>(set)</code> when anything inside holds a value, with the Start, End, Over and Then every shape shares; a Start or an End shows as a percentage, such as <code>50%</code>, once set, and as <code>(none)</code> while blank. The Scene page&#39;s and the clip page&#39;s Shapes tabs show them the same way. Swell accent follows the Swell, and Restart, when the ramps start over, ends the page.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Make a Shapes generator and add it to a chain, as <code>shapes: name</code>, to paint the same shapes on many clips and change them in one place. Density and Articulate can also be set in the <code>+ Density</code> and <code>+ Articulate</code> sections of a Scene page or a clip page. A Swell scales the notes on top of the Velocity and the velocity ramps of the scene and the clip, which are the plain way to make one scene louder or to fade one in and out: see <a href="./../SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>.</p><p><code>examples/by_genre/electronic/edm_density.yml</code> builds and breaks down an EDM track by Density alone. In <code>examples/learning/14_bolero_swell.yml</code>, the scenes&#39; velocity ramps make one long crescendo and a Shapes generator&#39;s Swell accent makes the timpani&#39;s downbeats land harder. <code>examples/learning/13_acid_articulate.yml</code> takes an acid house line from blips to slurs with Articulate.</p>',10)])])}const S=a(r,[["render",h]]);export{m as __pageData,S as default};
